import { defineStore } from 'pinia';
import { ref, computed, watch, inject, onScopeDispose, type ComputedRef } from 'vue';
import { ApiClient, defaultTokenStore, type AuthUser } from '../api/client';
import { ApiError } from '../api/errors';
import { useApiBase } from '../composables/useApiBase';
import { useMessages } from '../composables/useMessages';

/** The login path injected by the app (e.g. '/app/login'). Falls back to '/login'. */
type InjectedLoginPath = string | ComputedRef<string> | undefined;
function resolveLoginPath(injected: InjectedLoginPath): string {
    return typeof injected === 'string' ? injected : injected?.value ?? '/login';
}

/**
 * Parse the stable machine error code off a failed request, when the back end
 * carried one (`{ error, code }` envelope — same read as `useLibrariesStore`).
 * Returns `null` for network errors, non-ApiError throws, and bodies without a
 * usable `code`, so callers can distinguish "no code on the wire" from any
 * registered value. Error-code doctrine: components localize this code via the
 * `@phlix/contracts` registry catalog, never the server's English text.
 */
function parseErrorCode(e: unknown): string | null {
    if (!(e instanceof ApiError) || !e.body || typeof e.body !== 'object' || !('code' in e.body)) {
        return null;
    }
    return String((e.body as { code?: unknown }).code ?? '') || null;
}

/**
 * UI-m41 (review ui__fedev): the store's ONE live `phlix:auth-expired`
 * listener. The `window` binding is host-scoped while stores are pinia-scoped,
 * so a plain per-instantiation `addEventListener` accumulates one closure per
 * re-created store on hosts that rebuild Pinia (profile switch, re-auth, TV
 * remount): each dead closure pins its stale refs and fires on every dispatch.
 * Latest-wins — a fresh instantiation detaches its predecessor immediately,
 * and scope disposal (`disposePinia` / app unmount → the `onScopeDispose` arm,
 * the `usePreferencesStore` pagehide-pairing idiom) removes the last one.
 */
let activeAuthExpired: (() => void) | null = null;

export const useAuthStore = defineStore('auth', () => {
    // R-UI-10: resolve the store IN EFFECT at this store's creation (the pinia
    // setup runs on first use — the router guard — which is always AFTER
    // createPhlixApp registered any host token store, never a hardcoded
    // localStorage instance). It is passed explicitly to the client below so
    // token writes and Authorization reads share one instance.
    const tokenStore = defaultTokenStore();
    // The app's own API base, resolved reactively (a native client picks it at
    // runtime on the Connect screen, so it can change after this store — and its
    // client — already exist). The single `client` instance is kept (consumers
    // hold the reference); we re-point it in place whenever the base changes.
    const apiBase = useApiBase();
    // M-UI-10: the last-resort error lane speaks through the message catalog —
    // the same seam components use (`PhlixAppConfig.messages` override honored
    // inside an app context, English defaults outside one). Before this, the
    // store carried its own literals: the only "login" copy in a product that
    // everywhere else says "sign in", unperioded against the status-line law.
    const { t } = useMessages();
    // loginPath is set once at app boot (from config.routerBase) and never changes
    // after, but we watch it in case a native client ever supplies it as a ref.
    const injectedLoginPath = inject<InjectedLoginPath>('loginPath', '/login');
    const loginPath = computed(() => resolveLoginPath(injectedLoginPath));
    const client = new ApiClient({ tokenStore, baseUrl: apiBase.value, loginPath: loginPath.value });
    watch(apiBase, (base) => client.setBaseUrl(base));

    const user = ref<AuthUser | null>(null);
    const loading = ref(false);
    const error = ref<string | null>(null);
    // Stable machine code from the `{ error, code }` envelope of the last failed
    // request (null when the wire carried none). Components localize THIS, not
    // `error` — the server text is a debug fallback (error-code doctrine, W4).
    const errorCode = ref<string | null>(null);
    // Reactive mirror of the persisted token — localStorage reads aren't reactive,
    // so a plain computed over getAccessToken() would go stale after login/logout.
    const accessToken = ref<string | null>(tokenStore.getAccessToken());
    // Has the one-shot boot session check (init()) run yet? `isLoggedIn` is only a
    // token-PRESENCE flag; on a reload we must validate that token against the back
    // end before any guard trusts it. Memoised so concurrent navigations share one
    // /auth/me round-trip.
    const initialized = ref(false);
    let initPromise: Promise<void> | null = null;

    const isLoggedIn = computed(() => accessToken.value !== null);
    const isAdmin = computed(() => user.value?.is_admin === true);

    // M-UI-26: a determinatively dead refresh is cleared at the client (token
    // store + this event). Mirror it here so `isLoggedIn` goes false IMMEDIATELY
    // — previously a mid-session refresh failure left the store logged-in on
    // dead credentials until a page reload re-ran init(). No redirect and no
    // error fields: the router guards/pages own the UX (fetchUser-clears-state
    // precedent: the store owns the reactive vars, nothing louder).
    if (typeof window !== 'undefined') {
        if (activeAuthExpired) {
            window.removeEventListener('phlix:auth-expired', activeAuthExpired);
        }
        const onAuthExpired = () => {
            accessToken.value = null;
            user.value = null;
        };
        window.addEventListener('phlix:auth-expired', onAuthExpired);
        activeAuthExpired = onAuthExpired;
        onScopeDispose(() => {
            window.removeEventListener('phlix:auth-expired', onAuthExpired);
            if (activeAuthExpired === onAuthExpired) {
                activeAuthExpired = null;
            }
        });
    }

    /**
     * Adopt a freshly-minted token pair (login, signup, or the S81 profile
     * SWITCH response) into both the persistent store and the reactive mirror,
     * so `isLoggedIn` and every request's `Authorization` header follow the new
     * session. Exposed for `useProfileStore.switchTo` — a switch re-mints the
     * pair (the profile claim lives in the JWT); storing the old one would keep
     * the session on the previous profile until expiry.
     */
    function setTokens(access: string, refresh: string): void {
        tokenStore.setAccessToken(access);
        tokenStore.setRefreshToken(refresh);
        accessToken.value = access;
    }

    /**
     * Authenticate with a single identifier that may be EITHER a username or an
     * email. The value is always sent as `username`; it's ALSO sent as `email`
     * only when it looks like one (contains `@`). phlix-server reads `username`
     * (and falls back to an email lookup) and phlix-hub reads `username` then
     * `email`, so this satisfies both — while keeping a plain username out of any
     * `email` field a back end might format-validate up front.
     */
    async function login(identifier: string, password: string): Promise<boolean> {
        loading.value = true;
        error.value = null;
        errorCode.value = null;
        try {
            const body: Record<string, string> = { username: identifier, password };
            if (identifier.includes('@')) {
                body['email'] = identifier;
            }
            const data = await client.post<{
                access_token: string;
                refresh_token: string;
            }>('/api/v1/auth/login', body);

            setTokens(data.access_token, data.refresh_token);
            await fetchUser();
            // fetchUser() clears the tokens if it can't establish the user, so
            // report success only when the session actually stuck — a back end that
            // accepts the password but 404s/401s on /auth/me is treated as a failure.
            return isLoggedIn.value;
        } catch (e) {
            error.value = e instanceof Error ? e.message : t('auth.signInFailed');
            errorCode.value = parseErrorCode(e);
            return false;
        } finally {
            loading.value = false;
        }
    }

    async function signup(email: string, username: string, password: string): Promise<boolean> {
        loading.value = true;
        error.value = null;
        errorCode.value = null;
        try {
            const data = await client.post<{
                access_token: string;
                refresh_token: string;
            }>('/api/v1/auth/register', { email, username, password });

            setTokens(data.access_token, data.refresh_token);
            await fetchUser();
            // Same as login(): only report success if the session survived fetchUser().
            return isLoggedIn.value;
        } catch (e) {
            error.value = e instanceof Error ? e.message : t('auth.signupFailed');
            errorCode.value = parseErrorCode(e);
            return false;
        } finally {
            loading.value = false;
        }
    }

    async function fetchUser(): Promise<'valid' | 'invalid' | 'unreachable'> {
        if (!isLoggedIn.value) return 'valid';
        // Only a real attempt resets the code — the logged-out guard above keeps
        // a failure code the form is currently displaying from being wiped.
        errorCode.value = null;
        try {
            user.value = await client.getCurrentUser();
            return 'valid';
        } catch (e) {
            errorCode.value = parseErrorCode(e);
            user.value = null;
            if (e instanceof ApiError) {
                // The server ANSWERED and the session cannot load its own user —
                // determinative (401/403/404): clear. The pinned login-404 law
                // ("accepted password but /auth/me fails ⇒ logged out") keeps
                // every definitive answer's verdict semantics intact.
                tokenStore.clear();
                accessToken.value = null;
                return 'invalid';
            }
            // M4 (fedev review): NetworkError/TimeoutError (offline reload,
            // server restart) is *unknown*, not *rejected* — the same M-UI-26
            // law the client's refresh path already honors. A reload while the
            // server is briefly unreachable must not cost the user a valid
            // token: keep it, surface the connection error, and let init()
            // re-validate on the next protected navigation.
            error.value = e instanceof Error ? e.message : t('auth.serverUnreachable');
            return 'unreachable';
        }
    }

    /**
     * One-shot session bootstrap, run once from the router guard before the first
     * protected route resolves. A token restored from localStorage only makes
     * `isLoggedIn` true by its mere presence — it is NOT proof the session is still
     * valid. So if a token was restored, validate it against the back end exactly
     * once via {@link fetchUser}: a valid token populates `user` (so `isAdmin` and
     * the account badge are correct after a reload), and an invalid/expired token
     * is cleared by fetchUser() — which flips `isLoggedIn` to false so the guard
     * redirects to login instead of rendering protected/admin pages off a stale
     * token. A NETWORK failure is not a verdict (M4): the tokens are kept and the
     * memo is dropped so the next protected navigation retries. Memoised: the
     * validation runs at most once per conclusive outcome, and concurrent callers
     * await the same in-flight promise.
     */
    async function init(): Promise<void> {
        if (initialized.value) return;
        if (initPromise === null) {
            // fetchUser() is a no-op when there is no token; on a definitive
            // outcome it either populates `user` or clears the tokens.
            initPromise = fetchUser().then((outcome) => {
                if (outcome === 'unreachable') {
                    // M4: an offline boot is NOT a verdict. Drop the memo so the
                    // next protected navigation re-validates, instead of the
                    // guard trusting token-presence-without-user forever.
                    initPromise = null;
                    return;
                }
                initialized.value = true;
            });
        }
        return initPromise;
    }

    function logout(): void {
        // Delegate to the client so the loginPath-aware redirect is exercised.
        // Pass redirect=false so we handle navigation ourselves (consistent with
        // how fetchUser clears state on failure — the store owns the reactive vars).
        client.logout(false);
        accessToken.value = null;
        user.value = null;
        if (typeof window !== 'undefined') {
            window.location.href = loginPath.value;
        }
    }

    async function uploadAvatar(file: File): Promise<void> {
        loading.value = true;
        error.value = null;
        errorCode.value = null;
        try {
            const result = await client.uploadAvatar(file);
            if (user.value) {
                user.value.avatar_url = result.avatar_url;
            }
        } catch (e) {
            error.value = e instanceof Error ? e.message : 'Avatar upload failed';
            errorCode.value = parseErrorCode(e);
            throw e;
        } finally {
            loading.value = false;
        }
    }

    async function deleteAvatar(): Promise<void> {
        loading.value = true;
        error.value = null;
        errorCode.value = null;
        try {
            await client.deleteAvatar();
            if (user.value) {
                user.value.avatar_url = null;
            }
        } catch (e) {
            error.value = e instanceof Error ? e.message : 'Avatar deletion failed';
            errorCode.value = parseErrorCode(e);
            throw e;
        } finally {
            loading.value = false;
        }
    }

    return {
        user,
        loading,
        error,
        errorCode,
        isLoggedIn,
        isAdmin,
        client,
        login,
        signup,
        setTokens,
        fetchUser,
        init,
        logout,
        uploadAvatar,
        deleteAvatar,
    };
});
